def fit(a, b, method):

    def solve(w):
        return np.linalg.lstsq(a * w[:, None], b * w[:, None], rcond=None)[0]
    w = np.ones(len(a))
    floor = 1e-12 * max(1, np.median(abs(b)))
    if method == 'l1':
        for _ in range(32):
            coef = solve(w)
            e = np.linalg.norm(a @ coef - b, axis=1)
            w = 1 / np.sqrt(np.hypot(e, floor))
    elif method == 'radial':
        size = np.linalg.norm(b - np.median(b, axis=0), axis=1)
        w = np.minimum(1, (3 * np.median(size) / np.maximum(size, floor)) ** 2)
    for _ in range(16):
        coef = solve(w)
        e = np.linalg.norm(a @ coef - b, axis=1)
        w = 1 / np.hypot(1, e / max(0.3 * np.median(e), floor))
    good = e <= max(6 * np.median(e), floor)
    return (np.linalg.lstsq(a[good], b[good], rcond=None)[0], good)

def basis(x, name):
    from itertools import combinations_with_replacement
    z = [np.ones(len(x)), *x.T]
    pairs = [x[:, i] * x[:, j] for (i, j) in combinations_with_replacement(range(4), 2)]
    if name == 'aff':
        return np.array(z).T
    if name == 'diag2':
        return np.c_[np.array(z).T, x * x]
    if name.startswith('poly'):
        for d in range(2, int(name[-1]) + 1):
            z.extend((np.prod(x[:, ix], axis=1) for ix in combinations_with_replacement(range(4), d)))
    else:
        z += pairs
        (k, f) = name.split(':')
        a = float(k)
        z.extend({'sin': lambda : np.sin(a * x), 'tanh': lambda : np.tanh(a * x), 'rat': lambda : x / (1 + (a * x) ** 2), 'cub': lambda : x ** 3}[f]().T)
    return np.array(z).T

def _loads(calibration, split):
    raw = np.asarray(calibration['bridge_raw'])
    true = np.asarray(calibration['true_channel_loads'])
    (bridge, *_) = np.linalg.lstsq(np.column_stack([np.ones(len(true)), true]), raw, rcond=None)
    total = np.linalg.solve(bridge[1:], np.ones(4))
    return tuple(((np.asarray(split[key]) - bridge[0]) @ total for key in ('past_channel_raw', 'hold_channel_raw')))
